    global mod_additionnel_def
    def mod_additionnel_def():
        # Charger les mods depuis l'URL
        mods_list = load_mods_from_url()
        # Charger les états des QCheckBox
        saved_states = load_mod_states()

        # Parcourir la liste des mods et vérifier si le mod est additionnel
        for mod in mods_list:
            if mod["is_additional"]:
                print("passe3")
                widget_4 = QtWidgets.QWidget(parent=scrollAreaWidgetContents_4)
                widget_4.setObjectName("widget_4")
                gridLayout_13 = QtWidgets.QGridLayout(widget_4)
                gridLayout_13.setObjectName("gridLayout_13")

                page_label_name_mod_additionnel = QtWidgets.QLabel(parent=widget_4)
                page_label_name_mod_additionnel.setObjectName("page_label_name_mod_additionnel")
                page_label_name_mod_additionnel.setText(mod["name"])
                gridLayout_13.addWidget(page_label_name_mod_additionnel, 0, 1, 1, 1)

                checkBox = QtWidgets.QCheckBox(parent=widget_4)
                checkBox.setText("")
                checkBox.setObjectName("checkBox")
                gridLayout_13.addWidget(checkBox, 0, 0, 1, 1)

                verticalLayout_14.addWidget(widget_4)

                # Restaurer l'état du checkbox si sauvegardé
                if mod["name"] in saved_states:
                    checkBox.setChecked(saved_states[mod["name"]])

                # Connecter le signal stateChanged à la fonction save_mod_states
                checkBox.stateChanged.connect(save_mod_states)

                # Ajouter la QCheckBox au dictionnaire avec le nom du mod comme clé
                mod_checkboxes[mod["name"]] = checkBox

