def refresh_file_lists(minecraft_directory):
    global refresh_file_list
    global refresh_file_list_shaders
    global mod_additionnel_def
    refresh_file_list(minecraft_directory)
    refresh_file_list_shaders(minecraft_directory)
    mod_additionnel_def()
    save_mod_states()